//! Native LEGEND copies preserve actual independent attributes and source form state.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=owner><fieldset id=group><legend id=source align=initial>Legend<span> child</span></legend><input id=neighbor value=seed></fieldset></form><template id=parked><legend align=parked>Parked</legend></template></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://legend-import.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}

#[test]
fn legend_native_copy_shallow_has_native_owner_and_no_source_form(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var source=document.getElementById('source'),owner=document.getElementById('owner'),attr=source.getAttributeNode('align');source.align='A\ud800Z';var copy=source.cloneNode(false);if(!(copy instanceof HTMLLegendElement)||copy===source||copy.ownerDocument!==document||copy.parentNode!==null||copy.firstChild!==null||copy.form!==null||source.form!==owner||copy.align!==source.align||copy.getAttributeNode('align')===attr)throw 'actual native shallow copy';copy.align='independent';if(source.align!=='A\ud800Z'||attr.value!==source.align||document.getElementById('neighbor').value!=='seed')throw 'independent real native copy';"#);}
#[test]
fn legend_native_copy_inert_deep_import_preserves_exact_records_and_children(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),source=doc.createElementNS('http://www.w3.org/1999/xhtml','legend'),child=doc.createTextNode('R\udfffZ');source.align='A\ud800Z';source.appendChild(child);var copy=document.importNode(source,true);if(copy===source||copy.ownerDocument!==document||copy.form!==null||copy.align!==source.align||copy.firstChild===child||copy.firstChild.ownerDocument!==document||copy.firstChild.parentNode!==copy||copy.firstChild.data!=='R\udfffZ')throw 'actual native imported legend';copy.firstChild.data='changed';copy.align='changed';if(child.data!=='R\udfffZ'||source.align!=='A\ud800Z'||source.ownerDocument!==doc)throw 'independent native copy descendants';"#);}
#[test]
fn legend_native_copy_parked_import_keeps_template_source_topology(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var host=document.getElementById('parked'),source=host.content.firstChild,owner=source.ownerDocument,copy=document.importNode(source,true);if(!(copy instanceof HTMLLegendElement)||copy.align!=='parked'||copy.textContent!=='Parked'||copy.ownerDocument!==document||copy.firstChild.ownerDocument!==document||copy.firstChild===source.firstChild||source.parentNode!==host.content||source.ownerDocument!==owner||copy.form!==null)throw 'actual parked native imported legend';");}


#[test]
fn legend_native_copy_refusal_is_atomic_and_recovers(){
 for operation in ["clone","import"]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();let code=if operation=="clone"{run(&mut d,&mut f,&mut p,"var source=document.getElementById('source');");"var copy=source.cloneNode(true);"}else{run(&mut d,&mut f,&mut p,"var doc=new Document(),source=doc.createElementNS('http://www.w3.org/1999/xhtml','legend');source.align='exact';source.appendChild(doc.createTextNode('Fallback'));");"var copy=document.importNode(source,true);"};run(&mut d,&mut f,&mut p,"var first=source.firstChild,attr=source.getAttributeNode('align'),parent=source.parentNode,watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,childList:true,subtree:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;let nodes=p.state.node_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.node_limit=d.nodes.len(),_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{operation}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);p.state.retained_limit=limit;p.state.node_limit=nodes;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(source.firstChild!==first||source.parentNode!==parent||source.getAttributeNode('align')!==attr||watch.takeRecords().length)throw 'atomic copy refusal';");run(&mut d,&mut f,&mut p,code);run(&mut d,&mut f,&mut p,"if(copy===source||copy.ownerDocument!==document||copy.parentNode!==null||copy.firstChild===first||copy.align!==source.align||copy.textContent!==source.textContent||copy.form!==null||watch.takeRecords().length)throw 'actual fresh native copy recovery';");}}
}
#[test]
fn legend_native_copy_first_legend_control_state_and_actual_source_owner_are_preserved(){
 let mut d=crate::html::parse("<html><body><form id=owner><fieldset id=group disabled><legend id=source align=initial>First<input id=inside value=inside></legend><input id=outside value=outside></fieldset></form></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();run(&mut d,&mut f,&mut p,"var source=document.getElementById('source'),group=document.getElementById('group'),owner=document.getElementById('owner'),first=source.firstChild,copy=source.cloneNode(false);if(copy.form!==null||copy.firstChild!==null||copy.ownerDocument!==document||copy.align!=='initial'||source.form!==owner||group.firstChild!==source||source.firstChild!==first)throw 'independent shallow first legend copy';copy.align='changed';if(source.align!=='initial'||document.getElementById('inside').form!==owner||document.getElementById('outside').form!==owner)throw 'actual original owners preserved';");assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);
}
#[test]
fn legend_native_copy_remaining_active_descendant_and_handler_guards_preserve_sources(){
 let(mut d,mut f,mut p)=fixture();let n=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("source")).unwrap();if let NodeKind::Element{attrs,..}=&mut d.nodes[n].kind{attrs.push(crate::html::Attribute{name:crate::html::AttributeName::unqualified("onclick".into()),value:DomString::from("window.guard=1".to_owned())});}p.state.rebuild(&d).unwrap();run(&mut d,&mut f,&mut p,"var source=document.getElementById('source'),doc=new Document(),inert=doc.createElementNS('http://www.w3.org/1999/xhtml','legend'),frame=doc.createElementNS('http://www.w3.org/1999/xhtml','iframe');inert.appendChild(frame);");for code in ["source.cloneNode(true);","document.importNode(inert,true);"]{let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("support")||e.contains("unavailable")||e.contains("implemented"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(inert.firstChild!==frame||frame.parentNode!==inert||inert.ownerDocument!==doc||source.align!=='initial')throw 'active content copy guard';");}
}

#[test]
fn legend_native_copy_deep_native_clones_keep_independent_actual_children_and_attrs(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var source=document.getElementById('source'),first=source.firstChild,attr=source.getAttributeNode('align'),copy=source.cloneNode(true),list=copy.childNodes;if(copy.form!==null||source.form!==document.getElementById('owner')||copy.firstChild===first||copy.firstChild.ownerDocument!==document||copy.childNodes!==list||copy.textContent!=='Legend child'||copy.getAttributeNode('align')===attr)throw 'actual deep native clone';copy.firstChild.data='Changed\udfff';copy.align='Changed\ud800';if(source.firstChild!==first||source.textContent!=='Legend child'||source.align!=='initial'||copy.align!=='Changed\ud800'||copy.childNodes!==list)throw 'independent copied native records';"#);}
#[test]
fn legend_native_copy_does_not_open_unqualified_native_connection_or_inert_promotion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var source=document.getElementById('source'),group=document.getElementById('group'),owner=document.getElementById('owner'),copy=source.cloneNode(true),doc=new Document(),inert=doc.createElementNS('http://www.w3.org/1999/xhtml','legend');inert.align='inert';");for code in ["document.body.appendChild(copy);","group.appendChild(copy);","document.body.appendChild(inert);"]{let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("support")||e.contains("implemented")||e.contains("native")||e.contains("DOMException"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(copy.parentNode!==null||inert.parentNode!==null||inert.ownerDocument!==doc||source.parentNode!==group||group.firstChild!==source||source.form!==owner||copy.form!==null)throw 'retained connection boundaries';");}}
